testRunner.controllerProvider.register("beginTest", function ($scope, Popeye, $timeout, dateFilter) {
    $scope.readingTitle = `${testRunner.R.test.title}`;
    $scope.overlayDismissed = true;
    $scope.generalNotesInfoPanel = testRunner.R.test.generalNotesInfoPanel;
    $scope.generalNotes = testRunner.R.test.generalNotes;
    $scope.structureNotes = testRunner.R.test.structureNotes;
    $scope.termsAndConditions = testRunner.R.test.termsAndConditions;
    $scope.mode = "loading";

    $scope.year = (new Date()).getFullYear();

    if (testRunner.R.test.examType === 2 || testRunner.R.test.examType === 3) {
        $scope.state.phase = 1;
    }

    // Leaving "loading" is what actually lets the candidate start: the buttons in the other two panes
    // are gated on the terms checkbox only, not on the preload. So this must use the full
    // preloadCompleted() check — it used to compare the file count alone, which meant a preload that
    // had failed, or had filled a cache nothing can read, still opened the exam.
    $scope.$watchGroup(["preloadFilesCompleted", "preloadFilesNumber", "preloadFilesFailed",
                        "preloadCacheUsable"], function () {
        if ($scope.preloadCompleted()) {
            // (!realExam || (state.phase == 1 && state.readingTimeLeft > 0))
            if ($scope.generalNotes.length || $scope.structureNotes.length || $scope.termsAndConditions.length) {
                $scope.mode = "test_start_withdetails";
            } else {
                $scope.mode = "test_start";
            }
        }
    });

    function wordFormatDuration(durationInSec) {
        let numberFormatDuration = dateFilter(new Date(0, 0, 0, 0, 0, durationInSec), testRunner.settings.timeFormat);

        let parts = [];
        let words = numberFormatDuration.split(":");
        for (let i = 0; i < words.length; i++) {
            let val = parseInt(words[i]);
            if (val > 0) {
                let part = val + " ";
                switch (i) {
                    case 0:
                        part += "hour";
                        break;
                    case 1:
                        part += "minute";
                        break;
                    case 2:
                        part += "second";
                        break;
                }
                if (val > 1) part += "s";
                parts.push(part)
            }
        }
        return parts.join(" ");
    }
    $scope.readingTimeLeftWords = wordFormatDuration($scope.state.readingTimeLeft)

    $timeout(() => {
        $("#general-notes-info-panel").html($scope.generalNotesInfoPanel);
        $("#general-notes").html($scope.generalNotes);
        $("#structure-notes").html($scope.structureNotes);
        $("#terms-and-conditions").html($scope.termsAndConditions);
    });

    $scope.loginPrompt = function () {
        if ($scope.state.phase == 1 && $scope.state.readingTimeLeft > 0) {
            let modal = Popeye.openModal({
                template: testRunner.R.templates.loginConfirmModal.html,
                containerTemplate: testRunner.R.templates.modalContainer.html,
                scope: $scope,
                keyboard: false,
                click: false
            });
            modal.opened.then(function () {
                changeFontSizeIndex(Cookies.get("currentFontSizeIndex"));
            });
        } else {
            $scope.loginAgreed();
        }
    };

    $scope.loginAgreed = function () {
        // The integrity boundary is HERE, not the disabled buttons or the pane watcher. This modal can
        // already be open when the preload state goes bad — a controllerchange invalidates
        // preloadCacheUsable and re-probes, so the cache can stop being readable between the candidate
        // opening this confirmation and accepting it. Starting the exam is irreversible, so recheck.
        if (!$scope.preloadCompleted()) {
            console.error("preload: refusing to start the exam - the offline cache is not usable.");
            Popeye.closeCurrentModal(0);
            $scope.mode = "loading";
            return;
        }
        Popeye.closeCurrentModal(0);
        setPage("itemGroup");
    };
});

