testRunner.controllerProvider.register("break", function ($scope, $timeout, $interval, $window, dateFilter) {
    const minBreakTimeSecs = 60 * 5;
    $scope.timerHidden = testRunner.R.timerHidden == 1;
    $scope.readingTitle = `${testRunner.R.test.title} &ndash; Reading Time`;
    $scope.examTitle = `${testRunner.R.test.title}`;
    $scope.buttonDisabled = true;
    let restTimeLeftInitial = $scope.state.restTimeLeft;
    let startTime = new Date();
    let restTimer = null;
    let buttonTimer = null;
    $scope.restTimeLeftFormatted = dateFilter(new Date(0, 0, 0, 0, 0, $scope.state.restTimeLeft), testRunner.settings.timeFormat);
    $scope.state.resting = 1;

    let initializeTimer = function () {
        $interval.cancel(restTimer);

        $scope.state.restTimeLeft = Math.max(Math.round($scope.state.restTimeLeft), 1);
        $scope.restTimeLeftFormatted = dateFilter(new Date(0, 0, 0, 0, 0, $scope.state.restTimeLeft), testRunner.settings.timeFormat);
        restTimer = $interval(function () {
            timerTick();
        }, 1000);
        buttonTimer = $timeout(function () {
            $scope.buttonDisabled = false;
        }, minBreakTimeSecs * 1000);
    };

    let timerTick = function () {
        if ($scope.state.restTimeLeft > 0) {
            $scope.state.restTimeLeft = Math.round(restTimeLeftInitial - ((new Date()).getTime() - startTime.getTime()) / 1000);
            $scope.restTimeLeftFormatted = dateFilter(new Date(0, 0, 0, 0, 0, $scope.state.restTimeLeft), testRunner.settings.timeFormat);
        }
        if ($scope.state.restTimeLeft <= 0) {
            $scope.finishBreak();
        }
    };

    $scope.finishBreak = function () {
        setPage("itemGroup");
    };

    let beforeSubmitView = function () {
        $window.removeEventListener("beforeSubmitView", beforeSubmitView);
        $timeout.cancel(buttonTimer);
    };
    $window.addEventListener("beforeSubmitView", beforeSubmitView);

    let beforePageChanged = function () {
        $window.removeEventListener("beforePageChanged", beforePageChanged);
        $timeout.cancel(buttonTimer);
        $interval.cancel(restTimer);
        $scope.state.resting = 0;
    };
    $window.addEventListener("beforePageChanged", beforePageChanged);

    initializeTimer();
});

