testRunner.controllerProvider.register("itemGroup", function ($scope, $interval, dateFilter, Popeye, $window, $sce, $timeout, $compile) {
    testRunner.compileProvider.aHrefSanitizationWhitelist(/^\s*(https?|data):/);

    $scope.state.phase = Math.max($scope.state.phase, $scope.state.readingTimeLeft > 0 ? 2 : 3); //reading or test based on remaining reading time
    $scope.itemGroups = testRunner.R.safeItemGroups;
    $scope.itemGroup = null;
    $scope.itemGroupIndex = null;

    let readingTimeLeftInitial = $scope.state.readingTimeLeft;
    $scope.state.examTimeLeftInitial = $scope.state.examTimeLeft;
    $scope.timerHidden = testRunner.R.timerHidden == 1;
    $scope.$sce = $sce;

    $scope.readingTitle = `${testRunner.R.test.title} &ndash; Reading Time`;
    $scope.examTitle = `${testRunner.R.test.title}`;
    $scope.readingTimeLeftLabel = "Reading time left:";
    $scope.examTimeLeftLabel = "Time left:";
    $scope.readingTimeLeftFormatted = "";
    $scope.examTimeLeftFormatted = "";
    $scope.examTimeLeftWordsFormatted = "";
    $scope.restTimeLeftFormatted = dateFilter(new Date(0, 0, 0, 0, 0, $scope.state.restTimeLeft), testRunner.settings.timeFormat);
    let timerId = null;
    let swipeTimerId = null;
    $scope.lastLdbSwipeNum = 0;
    let startTime = null;
    $scope.finalSubmitStatus = 0;

    $scope.generalNotesInfoPanel = testRunner.R.test.generalNotesInfoPanel;
    $scope.generalNotes = testRunner.R.test.generalNotes;
    $scope.structureNotes = testRunner.R.test.structureNotes;
    $scope.layout = 0;
    $scope.layout_resizable = false;

    $scope.examTypes = { real: 0, sample: 1, familiarisation: 2, past: 3 };
    $scope.examType = testRunner.R.test.examType;

    let blurTolerance = 10;
    let noInputTolerance = 120;
    let lastBlurTime = null;
    let lastInputTime = null;
    let beforeCopyText = {};

    $scope.exportFileURIEncodedContent = null;
    $scope.exportFileName = null;
    for (let i = 0; i < $scope.state.itemGroups.length; i++) {
        let itemGroupState = $scope.state.itemGroups[i];
        itemGroupState.answered = itemGroupState.answered || false;

        for (let j = 0; j < itemGroupState.items.length; j++) {
            itemGroupState.items[j].answered = itemGroupState.items[j].answered || false;
        }
    }

    swipeTimerId = $interval(function () {
        let currentLdbSwipeNum = Cookies.get("rldbswipe");
        if (typeof (currentLdbSwipeNum) === 'undefined') return;
        if ($scope.lastLdbSwipeNum != currentLdbSwipeNum) {
            $scope.lastLdbSwipeNum = currentLdbSwipeNum;
        }
    }, 1000);

    $scope.$watch("lastLdbSwipeNum", function (newValue, oldValue) {
        if (newValue > 0 && newValue != oldValue) {
            alert("This session is being monitored. Please return to the exam.");
        }
    });

    $scope.canRest = function () {
        return $scope.state.restTimeLeft >= 60 * 4;
    };

    $scope.backToTop = function () {
        window.scrollTo(0, 0);
    };

    $scope.getUnattemptedQuestionsNum = function () {
        let unanswered = 0;
        for (let i = 0; i < $scope.state.itemGroups.length; i++) {
            let itemGroupState = $scope.state.itemGroups[i];
            if (!itemGroupState.answered) unanswered++;
        }
        return unanswered;
    };

    $scope.getFlaggedQuestionsNum = function () {
        let flagged = 0;
        for (let i = 0; i < $scope.state.itemGroups.length; i++) {
            if ($scope.state.itemGroups[i].flagged) flagged++;
        }
        return flagged;
    };

    function wordFormatDuration(durationInSec) {
        let numberFormatDuration = dateFilter(new Date(0, 0, 0, 0, 0, durationInSec), testRunner.settings.timeFormat);

        let parts = [];
        let words = numberFormatDuration.split(":");
        for (let i = 0; i < words.length; i++) {
            let val = parseInt(words[i]);
            if (val > 0) {
                let part = val + " ";
                switch (i) {
                    case 0:
                        part += "hour";
                        break;
                    case 1:
                        part += "minute";
                        break;
                    case 2:
                        part += "second";
                        break;
                }
                if (val > 1) part += "s";
                parts.push(part)
            }
        }
        return parts.join(" ");
    }

    $scope.initializeTimer = function () {
        if ($scope.examType === $scope.examTypes.real || $scope.examType === $scope.examTypes.sample) {
            $interval.cancel(timerId);
            startTime = new Date();

            $scope.state.readingTimeLeft = Math.max(Math.round($scope.state.readingTimeLeft), 0);
            if ($scope.state.readingTimeLeft == 0 && !$scope.isExamStarted()) $scope.state.readingTimeLeft = 1;
            $scope.state.examTimeLeft = Math.max(Math.round($scope.state.examTimeLeft), 0);
            if ($scope.state.examTimeLeft == 0 && !$scope.isExamFinished()) $scope.state.examTimeLeft = 1;
            if ($scope.state.readingTimeLeft + $scope.state.examTimeLeft > 0) {
                $scope.readingTimeLeftFormatted = dateFilter(new Date(0, 0, 0, 0, 0, $scope.state.readingTimeLeft), testRunner.settings.timeFormat);
                $scope.examTimeLeftFormatted = dateFilter(new Date(0, 0, 0, 0, 0, $scope.state.examTimeLeft), testRunner.settings.timeFormat);
                $scope.examTimeLeftWordsFormatted = wordFormatDuration($scope.state.examTimeLeft);
                if (!$scope.isExamFinished()) {
                    timerId = $interval(function () {
                        $scope.timerTick();
                    }, 1000);
                }
            }
        }
    };

    $scope.timerTick = function () {
        if ($scope.isExamStarted()) {
            if ($scope.state.examTimeLeft > 0) {
                $scope.state.examTimeLeft = Math.round($scope.state.examTimeLeftInitial - ((new Date()).getTime() - startTime.getTime()) / 1000);
                $scope.examTimeLeftFormatted = dateFilter(new Date(0, 0, 0, 0, 0, $scope.state.examTimeLeft), testRunner.settings.timeFormat);
                $scope.examTimeLeftWordsFormatted = wordFormatDuration($scope.state.examTimeLeft);
                $scope.itemGroupState.timeTaken += Math.round(((new Date()).getTime() - $scope.itemGroupState.startTime.getTime()) / 1000);
                $scope.itemGroupState.startTime = new Date();
            }
            if ($scope.state.examTimeLeft <= 0) {
                $scope.finishExam(3);
            }
        } else {
            if ($scope.state.readingTimeLeft > 0) {
                $scope.state.readingTimeLeft = Math.round(readingTimeLeftInitial - ((new Date()).getTime() - startTime.getTime()) / 1000);
                $scope.readingTimeLeftFormatted = dateFilter(new Date(0, 0, 0, 0, 0, $scope.state.readingTimeLeft), testRunner.settings.timeFormat);
                $scope.itemGroupState.timeTaken += Math.round(((new Date()).getTime() - $scope.itemGroupState.startTime.getTime()) / 1000);
                $scope.itemGroupState.startTime = new Date();
            }
            if ($scope.state.readingTimeLeft <= 0) {
                $scope.outOfReadingTime();
            }
        }
    };

    $scope.info = function () {
        let modal = Popeye.openModal({
            template: testRunner.R.templates.infoModal.html,
            containerTemplate: testRunner.R.templates.modalContainerLarge.html,
            scope: $scope,
            keyboard: true,
            click: true
        });
        modal.opened.then(function () {
            $(".info-content").html($scope.generalNotesInfoPanel);
            $(".popeye-modal div.clickable").focus();
            if (Cookies.get("currentFontSize") !== "1em") {
              let currentFontSize = Cookies.get("currentFontSize") || "1em";

              const ratio = parseFloat(currentFontSize.replace(/em$/, ""));
              const conv14 = Math.round(14 * ratio);
              const conv20 = Math.round(20 * ratio);

              $("a").css("font-size", conv14 + "px");
              $("h4").css("font-size", conv20 + "px");

              $('a[href="https://docs.webix.com/diagram__userguide.html"]')
                .closest("div")
                .css("margin-bottom", "1rem");
              $(
                'a[href="https://webix-guides.gitbook.io/spreadsheet-user-guide/"]'
              )
                .closest("div")
                .css("margin-bottom", "1rem");
            }
        });
        modal.closed.then(function () {
            $(".nav-toolbar-button-top-info").focus();
            $("a, h4").css("font-size", "");
            $('a[href="https://docs.webix.com/diagram__userguide.html"]')
              .closest("div")
              .css("margin-bottom", "");
            $(
              'a[href="https://webix-guides.gitbook.io/spreadsheet-user-guide/"]'
            )
              .closest("div")
              .css("margin-bottom", "");
        });
    };

    $scope.changePhase = (newPhase) => {
        $scope.state.phase = newPhase;
    }

    $scope.changeItemGroup = function (index) {
        const destroy = [];

        if (index === $scope.itemGroupIndex) return;
        if ($scope.items) {
            for (let i = 0; i < $scope.items.length; i++) {
                let item = $scope.items[i];
                if (item.busy) return;
                if (item.destroy) destroy.push(item.destroy);
            }
        }

        destroy.map(fn => fn());

        $window.dispatchEvent(new Event("beforeItemGroupChanged"));

        clearFlags();
        updateState();

        $scope.itemGroup = $scope.itemGroups[index];
        $scope.itemGroupIndex = index;
        $scope.itemGroupState = $scope.state.itemGroups[index];
        $scope.itemGroupState.startTime = new Date();
        if ($scope.itemGroupState.mode === undefined) {
            if ($scope.itemGroup.electives === undefined || $scope.itemGroup.electives.length === 0) {
                $scope.itemGroupState.mode = "simple";
            } else {
                $scope.itemGroupState.mode = "select_elective";
                $scope.itemGroupState.selectedElective = null;
            }
        }
        $scope.items = getItems($scope.itemGroupState.mode, $scope.itemGroup, $scope.itemGroupState);
        $scope.layout = $scope.itemGroupState.mode !== "elective" || $scope.itemGroupState.selectedElective === undefined || $scope.itemGroupState.selectedElective.layout === undefined
            ? $scope.itemGroup.layout
            : $scope.itemGroupState.selectedElective.layout;
        $scope.layout_resizable = $scope.itemGroupState.mode !== "elective" || $scope.itemGroupState.selectedElective === undefined || $scope.itemGroupState.selectedElective.layout_resizable === undefined
            ? $scope.itemGroup.layout_resizable
            : $scope.itemGroupState.selectedElective.layout_resizable;
		$scope.resetNavigationRange(index, $scope.navigationRange.max);
		$scope.initialAdjustmentSize = $scope.layout == 2 ? [67, 33] : ($scope.layout == 3 ? [33, 67] : [50,50]);
		$scope.adjustmentSize = $scope.itemGroupState.mode !== "elective"
			? (
				$scope.itemGroupState.adjustmentMove === true 
					? $scope.itemGroupState.adjustmentSize 
					: $scope.initialAdjustmentSize
			)
			: (
				$scope.itemGroupState.selectedElective?.adjustmentMove === true
					? $scope.itemGroupState.selectedElective.adjustmentSize
					: $scope.initialAdjustmentSize
			);
        $scope.highlighter = null;

        $timeout(function () {
            changeFontSizeIndex(Cookies.get("currentFontSizeIndex"));
            switch ($scope.itemGroupState.mode) {
                case "simple": case "elective":
                    initializeHighlight();
                    break;
                case "select_elective":
                    initializeElectives();
                    break;
            }
            updateContentTop();
            setupFullscreenElements();
            initializeSplit();
            setupAccordianElements();
        }, 0);

        initializeFlags();
    };

    $scope.selectElective = function (elective) {
        updateState();
        $scope.itemGroupState.selectedElective = elective;
        $scope.itemGroupState.mode = "elective";
        $scope.itemGroupState.answered = $scope.calculateAnswered();
        $scope.layout = $scope.itemGroupState.selectedElective.layout === undefined ? $scope.itemGroup.layout : $scope.itemGroupState.selectedElective.layout;
        $scope.layout_resizable = $scope.itemGroupState.selectedElective.layout_resizable === undefined ? $scope.itemGroup.layout_resizable : $scope.itemGroupState.selectedElective.layout_resizable;
		$scope.initialAdjustmentSize = $scope.layout === 2 ? [67, 33] : ($scope.layout === 3 ? [33, 67] : [50,50]);
		$scope.adjustmentSize = $scope.itemGroupState.selectedElective.adjustmentMove === undefined ? 
								$scope.initialAdjustmentSize : $scope.itemGroupState.selectedElective.adjustmentSize;
        $scope.items = getItems($scope.itemGroupState.mode, $scope.itemGroup, $scope.itemGroupState);
        $timeout(function () {
            initializeHighlight();
            setupFullscreenElements();
            initializeSplit();
            setupAccordianElements();
        }, 0);
    } 

    $scope.deselectElective = function (elective) {
        updateState();
        $scope.itemGroupState.mode = "select_elective";
        $scope.itemGroupState.selectedElective = null;
        $scope.itemGroupState.answered = false;
        $scope.layout = $scope.itemGroup.layout;
        $scope.layout_resizable = $scope.itemGroup.layout_resizable;
		$scope.initialAdjustmentSize = $scope.layout === 2 ? [67, 33] : ($scope.layout === 3 ? [33, 67] : [50,50]);
		$scope.adjustmentSize = $scope.itemGroupState.adjustmentMove === undefined ? 
								$scope.initialAdjustmentSize : $scope.itemGroupState.adjustmentSize;
        $timeout(function () {
            initializeElectives();
            setupAccordianElements();
			initializeSplit();
        });
    }

	// adjustment bar
	var splitInstance;
	function initializeSplit() {
		if (splitInstance) {
			// Destroy Split.js
			splitInstance.destroy();
			splitInstance = null;
		}
		if (document.querySelector('.item-group-two-col') && !splitInstance && $scope.layout_resizable) {
			var containerWidth = document.getElementById('splitContainer').offsetWidth;
			var minSizeInPixels = containerWidth * 0.33;

			splitInstance = Split(['#split-0', '#split-1'], {
				sizes: $scope.adjustmentSize,      
				minSize: minSizeInPixels,   
				gutterSize: 10,     
				cursor: 'col-resize',  
				// Save the size when the bar dragging is complete
				onDragEnd: function(sizes) {
					$scope.$apply(function() {
						if ($scope.itemGroupState.mode === "elective" && $scope.itemGroupState.selectedElective) {
							$scope.itemGroupState.selectedElective.adjustmentSize = sizes;
							$scope.itemGroupState.selectedElective.adjustmentMove = true;
						} else {
							$scope.itemGroupState.adjustmentSize = sizes;
							$scope.itemGroupState.adjustmentMove = true;
						}

					});
				}
			});
		} 
	}

    $scope.showPrescribedTexts = function () {
        let modal = Popeye.openModal({
            template: `
                <div style="position: absolute; right: 0; top: 0; height: 100%;">
                    <div class="clickable" ng-click="closeModal()" ng-keypress="closeModal()" style="position: sticky; top: 0; padding: 8px; background: rgb(184, 18, 55); color: #ffffff;" tabindex="0">
                        Close this screen X
                    </div>
                </div>

                ${$scope.itemGroupState.selectedElective.texts}
            `,
            containerTemplate: `
                <div class="popeye-modal-container modal-container">
                    <div class="popeye-modal modal-medium">
                    </div>
                </div>
            `,
