    let clearFlags = function () {
        lastBlurTime = null;
        lastInputTime = null;
        beforeCopyText = {};

        $(function () {
            $(window).off("focus");
            $(window).off("blur");
            $("input:text, textarea").off("paste");
            $("input:text, textarea").off("cut");
            $("input:text, textarea").off("copy");
            $(window).off("mousemove keydown");
        });
    };

    let onWindowBlur = function () {
        lastBlurTime = new Date();
    };

    let onWindowFocus = function () {
        if (lastBlurTime !== null) {
            let diff = (new Date() - lastBlurTime) / 1000;
            if (diff > blurTolerance) {
                console.log("long blur detected");
                $scope.itemGroupState.flags = $scope.itemGroupState.flags | 1;
                let flagsDetailed = $scope.itemGroupState.flagsDetailed;
                if (!flagsDetailed.hasOwnProperty("f1")) {
                    flagsDetailed.f1 = {};
                }
                if (!flagsDetailed.f1.hasOwnProperty("timeBlurred")) {
                    flagsDetailed.f1.timeBlurred = [];
                }
                flagsDetailed.f1.timeBlurred = flagsDetailed.f1.timeBlurred.concat(diff);
            }
        }
    };

    let onCopy = function (ev) {
        let contentText = $(ev.target).val().replace(/\r/g, "");
        beforeCopyText[ev.target.name] = contentText;
    };

    let beforeCopyTextContains = function (name, text) {
        if (name in beforeCopyText) {
            return beforeCopyText[name].indexOf(text) !== -1;
        }
        return false;
    };

    let onPaste = function (ev) {
        let pastedText = "";
        if (ev.originalEvent.clipboardData) pastedText = ev.originalEvent.clipboardData.getData('text');
        else if (window.clipboardData) pastedText = window.clipboardData.getData('text');
        pastedText = pastedText.replace(/\r/g, "");
        if (!pastedText) return;
        let contentText = $(ev.target).val().replace(/\r/g, "");
        let name = ev.target.name;
        if (contentText.indexOf(pastedText) === -1 && !beforeCopyTextContains(name, pastedText)) {
            console.log("invalid paste content detected");
            $scope.itemGroupState.flags = $scope.itemGroupState.flags | 2;
            let flagsDetailed = $scope.itemGroupState.flagsDetailed;
            if (!flagsDetailed.hasOwnProperty("f2")) {
