            if (!flagsDetailed.f2.hasOwnProperty("textPasted")) {
                flagsDetailed.f2.textPasted = [];
            }
            flagsDetailed.f2.textPasted = flagsDetailed.f2.textPasted.concat(pastedText);
        }
    };

    let onUserInput = function () {
        if (lastInputTime !== null) {
            let diff = (new Date() - lastInputTime) / 1000;
            if (diff > noInputTolerance) {
                console.log("long idle period detected");
                $scope.itemGroupState.flags = $scope.itemGroupState.flags | 4;
                let flagsDetailed = $scope.itemGroupState.flagsDetailed;
