            (eventName === "changecolours" && (bgColorCurrent !== defaultBGColor || fgColorCurrent !== defaultFGColor)) ||
            (eventName === "changehighlighter" && $scope.highlighter !== null)

        const onEvent = (ev) => {
            $(`#${name}`).remove();

            if (isNotDefault(ev.type)) {
                const css = fnCSS(ev);

                if (css && css.length) {
                    $("head").append(`<style id='${name}'>${css}</style>`);
                }
            }

            fnAfterCSS(ev);
        }

        const events = { "font":["changefontsize"], "colours":["changecolours"], "highlight":["changehighlighter","highlight"] }
        for (let eventName of events[event]) {
            document.addEventListener(eventName, onEvent, false);
            if (isNotDefault(eventName)) {
                onEvent(new CustomEvent(events[event]));
            }
        }

        return () => {
            for (let eventName of events[event]) document.removeEventListener(eventName, onEvent);
            $(`#${name}`).remove();
        }
    }
