    $scope.resetNavigationRange = function(index, max) {
        if (max >= $scope.navigationRange.total) {
            $scope.navigationRange = {
                index,
                start: 0,
                end: $scope.navigationRange.total,
                max: $scope.navigationRange.total,
                total: $scope.navigationRange.total,
                previous: false,
                next: false
            };
            return;
        }

        const before = Math.round((max - 1) / 2);
        const after = max - before - 1;
        const newRange = {
            index,
            start: $scope.itemGroupIndex - before,
            end: $scope.itemGroupIndex + after + 1,
            max: max,
            total: testRunner.R.safeItemGroups.length,
            //previous: $scope.itemGroupIndex !== 0,
            //next: $scope.itemGroupIndex !== testRunner.R.safeItemGroups.length - 1
        };

        if (newRange.start < 0) {
            newRange.start = 0;
            newRange.end = newRange.max;
        }
        if (newRange.end > newRange.total) {
            newRange.start = newRange.total - newRange.max;
            newRange.end = newRange.total;
        }

        newRange.previous = newRange.start !== 0
        if (newRange.previous) newRange.start += 1

        newRange.next = newRange.end !== newRange.total
        if (newRange.next) newRange.end -= 1

        $scope.navigationRange = newRange;
    }

    $scope.checkNavigationRangeSize = () => {
