    $scope.moveNavigationRange = function(increment) {
        const {index, start, end, max, total, previous, next} = $scope.navigationRange;
        const newRange = {
            index,
            start: start + increment,
            end: end + increment,
            max,
            total,
            previous,
            next
        }

        if (previous) {
            if (newRange.start === 1) {
                newRange.start = 0;
                newRange.previous = false;
            }
        }
        else if (newRange.start > 0) {
            newRange.start += 1;
            newRange.previous = true;
        }

        if (next) {
            if (newRange.end === newRange.total - 1) {
                newRange.end = newRange.total;
                newRange.next = false;
            }
        }
        else if (newRange.end < newRange.total) {
            newRange.end -= 1;
            newRange.next = true;
        }

        $scope.navigationRange = newRange;
    }

