    function addTextNodeRange(elem, userRange, ranges) {
        if (elem === userRange.endContainer) return;
        if (elem.nodeType !== Node.TEXT_NODE) {
            for (let i = 0; i < elem.childNodes.length; i++) {
                let child = elem.childNodes[i];
                addTextNodeRange(child, userRange, ranges);
            }
        } else {
            let newRange = document.createRange();
            newRange.setStart(elem, 0);
            newRange.setEndAfter(elem);
            ranges.push(newRange);
        }
    }

    function addMidTextNodesRange(elem, userRange, ranges) {
        let startContainerIndex = null;
        let endContainerIndex = null;
        for (let i = 0; i < elem.childNodes.length; i++) {
            let child = elem.childNodes[i];

            if (child.contains(userRange.startContainer)) startContainerIndex = i;
            if (child.contains(userRange.endContainer)) endContainerIndex = i;
        }

        for (let i = 0; i < elem.childNodes.length; i++) {
            let child = elem.childNodes[i];

            if (i === startContainerIndex || i === endContainerIndex) addMidTextNodesRange(child, userRange, ranges);
            else if ((startContainerIndex === null || startContainerIndex < i) && (endContainerIndex === null || endContainerIndex > i)) addTextNodeRange(child, userRange, ranges);
        }
    }

    function getSafeRanges(userRange) {
        let ranges = [];
        let startElem = userRange.startContainer;
        let endElem = userRange.endContainer;

        //start
        if (startElem.nodeType === Node.TEXT_NODE) {
            if (startElem === endElem) {
                ranges.push(userRange);
                return ranges;
            } else {
                let newRange = document.createRange();
                newRange.setStart(startElem, userRange.startOffset);
                newRange.setEndAfter(startElem);
                ranges.push(newRange);
            }
        }

        //middle
        let ancestor = userRange.commonAncestorContainer;
        addMidTextNodesRange(ancestor, userRange, ranges);

        let sibling = startElem.nextSibling;
        while (sibling) {
            addTextNodeRange(sibling, userRange, ranges);
            sibling = sibling.nextSibling;
        }

        //end
        if (endElem.nodeType === Node.TEXT_NODE) {
            let newRange = document.createRange();
            newRange.setStart(endElem, 0);
            newRange.setEnd(endElem, userRange.endOffset);
            ranges.push(newRange);
        }

        return ranges;
    }

