            .css({ "font-size": `${16 * fontRatio}px` })
            .find(".hsc-tooltip").css({ "font-size": `${16 * fontRatio}px` }).end()
            .find(".hsc-tooltiptext").css({ "position": "fixed", "left": 12, "font-size": `${16 * fontRatio}px` }).end();
        $(".webix_window .webix_layout_toolbar .webix_template").css({ "overflow-y": "hidden" });
    }

    const setupFullscreenElements = () => {
        const exitFullscreen = (el) => {
            $("#fullscreen-window-css").remove();
            webix.fullscreen.exit()
            $("body").css("overflow", "auto");
        }
        const setElementFullscreen = (ev) => {
            if (ev.target.tagName === "INPUT" || ev.target.tagName === "SELECT" || ev.target.tagName === "TEXTAREA") return
            if ($(ev.target).closest(".webix_window").length) return

            const title = ev.currentTarget.classList.contains('zoom-panel')
                ? `<div id="full-title">${$scope.itemGroup.title}</div>`
                : `<h5>${ev.currentTarget.title}</h5>`;

            $scope.openFullscreenWindow(
                ev.currentTarget,
                ev.currentTarget.clientWidth,
                title,
                exitFullscreen
            )
        }
        $(document).ready(() => {
            $(".zoom-window").on("click", setElementFullscreen)
        })  
    }

    $scope.takeBreak = function () {
        setPage("takeBreak");
    };

    let finalSubmit = function () {
        $scope.finalSubmitStatus = 0;
        testRunner.runWorker("persist", {
            finalSubmit: 1,
            status: $scope.state.status,
        }, function success() {
            $scope.finalSubmitStatus = 1;
            $scope.changePhase(5);
        }, function failure() {
            $scope.finalSubmitStatus = 2;
            $timeout(function () {
                finalSubmit();
            }, 5000);
        });
    };

    let initializeExportFile = function () {
        $scope.exportFileURIEncodedContent = encodeURIComponent(JSON.stringify($scope.state));
        $scope.exportFileName = testRunner.R.studentNumber + "-" + $scope.state.id + "-" + $scope.state.timestamp + ".yml";
    };

    $scope.changeItemGroup(0);
    $scope.initializeTimer();
    if ($scope.isExamStarted()) {
        $scope.openReport();
    }

    let beforePageChanged = function () {
        $window.removeEventListener("beforePageChanged", beforePageChanged);
        $interval.cancel(timerId);
        $interval.cancel(swipeTimerId);
        updateState();
        stopAllMedia();
        clearFlags();
    };
    $window.addEventListener("beforePageChanged", beforePageChanged);

    let beforeSubmitView = function () {
        $window.removeEventListener("beforeSubmitView", beforeSubmitView);
        $interval.cancel(timerId);
        $interval.cancel(swipeTimerId);
        updateState();
    };
    $window.addEventListener("beforeSubmitView", beforeSubmitView);

    let beforeAutoSave = function () {
        $window.removeEventListener("beforeAutoSave", beforeAutoSave);
        updateState();
    };
    $window.addEventListener("beforeAutoSave", beforeAutoSave);

    if ($scope.isExamFinished()) {
        $scope.finishExam($scope.state.status);
    }


// Listen for window resize and update the minimum width
$window.addEventListener('resize', function() {
    if (splitInstance) {
		initializeSplit();
    }
});

$timeout(function () {
    initializeSplit();
}, 0);

})
;

